#define main historical_main
#include "../bspline-vgh-cuda/main.cu"
#undef main
#undef max
#undef min
#include <vector>
#include <algorithm>
#include <filesystem>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{float*coefs,*vals,*grads,*hess;std::vector<double>gold,ideal;std::vector<float>ref;int kind;};
void ideal_weights(double t,double*a,double*d,double*d2){a[0]=pow(1-t,3)/6;a[1]=(3*t*t*t-6*t*t+4)/6;a[2]=(-3*t*t*t+3*t*t+3*t+1)/6;a[3]=t*t*t/6;d[0]=-.5*(1-t)*(1-t);d[1]=1.5*t*t-2*t;d[2]=-1.5*t*t+t+.5;d[3]=.5*t*t;d2[0]=1-t;d2[1]=3*t-2;d2[2]=1-3*t;d2[3]=t;}
std::vector<double> oracle(std::vector<float>&cf,std::vector<float>&basis,bool ideal){std::vector<double>v(4*2003,-123.25),g(4*6012,-123.25),h(4*18036,-123.25);double frac[4][3]={{0,0,0},{.25,.5,.75},{.875,.125,.625},{.5,.25,.125}};for(int walker=0;walker<4;walker++){int wb=walker*42,ix=basis[wb+36],iy=basis[wb+37],iz=basis[wb+38];double w[3][3][4];for(int axis=0;axis<3;axis++){if(ideal)ideal_weights(frac[walker][axis],w[0][axis],w[1][axis],w[2][axis]);else for(int d=0;d<3;d++)for(int q=0;q<4;q++)w[d][axis][q]=basis[wb+(d*3+axis)*4+q];}for(int n=0;n<2003;n++){double a[10]={};for(int i=0;i<4;i++)for(int j=0;j<4;j++)for(int k=0;k<4;k++){double c=cf[((ix+i)*25+(iy+j)*5+iz+k)*2016+n];a[0]+=c*w[0][0][i]*w[0][1][j]*w[0][2][k];a[1]+=c*w[1][0][i]*w[0][1][j]*w[0][2][k];a[2]+=c*w[0][0][i]*w[1][1][j]*w[0][2][k];a[3]+=c*w[0][0][i]*w[0][1][j]*w[1][2][k];a[4]+=c*w[2][0][i]*w[0][1][j]*w[0][2][k];a[5]+=c*w[1][0][i]*w[1][1][j]*w[0][2][k];a[6]+=c*w[1][0][i]*w[0][1][j]*w[1][2][k];a[7]+=c*w[0][0][i]*w[2][1][j]*w[0][2][k];a[8]+=c*w[0][0][i]*w[1][1][j]*w[1][2][k];a[9]+=c*w[0][0][i]*w[0][1][j]*w[2][2][k];}v[walker*2003+n]=a[0];int gb=walker*6012+n*3,hb=walker*18036+n*9;double dx=5,dy=7,dz=9;g[gb]=a[1]*dx;g[gb+1]=a[2]*dy;g[gb+2]=a[3]*dz;h[hb]=a[4]*dx*dx;h[hb+1]=h[hb+3]=a[5]*dx*dy;h[hb+2]=h[hb+6]=a[6]*dx*dz;h[hb+4]=a[7]*dy*dy;h[hb+5]=h[hb+7]=a[8]*dy*dz;h[hb+8]=a[9]*dz*dz;}}v.insert(v.end(),g.begin(),g.end());v.insert(v.end(),h.begin(),h.end());return v;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;std::vector<float>basis(168);auto name=std::filesystem::path(__FILE__).parent_path()/"study_basis.bin";FILE*f=fopen(name.c_str(),"rb");if(!f||fread(basis.data(),4,168,f)!=168)return 3;fclose(f);float*dw;CK(cudaMalloc(&dw,168*4));CK(cudaMemcpy(dw,basis.data(),168*4,cudaMemcpyHostToDevice));std::vector<Case>cases;std::vector<float>prefix;for(int kind=0;kind<2;kind++){Case c;c.kind=kind;std::vector<float>coefs;for(int x=0;x<5;x++)for(int y=0;y<5;y++)for(int z=0;z<5;z++)for(int n=0;n<2016;n++)coefs.push_back(!kind?float(n%17-8)/16.f:float((n*17+x*x*13+y*y*7+z*z*3+x*y*11+y*z*5+x*z*3+n*(x+2*y+3*z))%251-125)/256.f);c.gold=oracle(coefs,basis,false);c.ideal=oracle(coefs,basis,true);prefix.insert(prefix.end(),coefs.begin(),coefs.end());std::vector<float>rv(4*2003,-123.25f),rg(4*6012,-123.25f),rh(4*18036,-123.25f);for(int walker=0;walker<4;walker++){int wb=walker*42;bspline_ref(coefs.data(),2016*25,2016*5,2016,rv.data(),rg.data(),rh.data(),basis.data()+wb,basis.data()+wb+4,basis.data()+wb+8,basis.data()+wb+12,basis.data()+wb+16,basis.data()+wb+20,basis.data()+wb+24,basis.data()+wb+28,basis.data()+wb+32,5,7,9,2003,walker,basis[wb+36],basis[wb+37],basis[wb+38]);}c.ref=rv;c.ref.insert(c.ref.end(),rg.begin(),rg.end());c.ref.insert(c.ref.end(),rh.begin(),rh.end());CK(cudaMalloc(&c.coefs,coefs.size()*4));CK(cudaMalloc(&c.vals,rv.size()*4));CK(cudaMalloc(&c.grads,rg.size()*4));CK(cudaMalloc(&c.hess,rh.size()*4));CK(cudaMemcpy(c.coefs,coefs.data(),coefs.size()*4,cudaMemcpyHostToDevice));std::vector<float>iv(rv.size(),-123.25f),ig(rg.size(),-123.25f),ih(rh.size(),-123.25f);CK(cudaMemcpy(c.vals,iv.data(),iv.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.grads,ig.data(),ig.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.hess,ih.data(),ih.size()*4,cudaMemcpyHostToDevice));cases.push_back(c);}prefix.insert(prefix.end(),basis.begin(),basis.end());auto launch=[&](Case&c,int walker){int wb=walker*42;bspline<<<8,256>>>(c.coefs,2016*25,2016*5,2016,c.vals,c.grads,c.hess,dw+wb,dw+wb+4,dw+wb+8,dw+wb+12,dw+wb+16,dw+wb+20,dw+wb+24,dw+wb+28,dw+wb+32,5,7,9,2003,walker,basis[wb+36],basis[wb+37],basis[wb+38]);};for(auto&c:cases)for(int walker=0;walker<4;walker++)launch(c,walker);CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){auto output=prefix;std::vector<double>times;double seconds=0,ma=0,ie=0,ce=0,sym=0,referr=0;bool ok=true;for(auto&c:cases){for(int walker=0;walker<4;walker++){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)launch(c,walker);CK(cudaDeviceSynchronize());double one=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;seconds+=one;times.push_back(one);}std::vector<float>v(4*2003),g(4*6012),h(4*18036);CK(cudaMemcpy(v.data(),c.vals,v.size()*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(g.data(),c.grads,g.size()*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(h.data(),c.hess,h.size()*4,cudaMemcpyDeviceToHost));auto got=v;got.insert(got.end(),g.begin(),g.end());got.insert(got.end(),h.begin(),h.end());for(size_t q=0;q<got.size();q++){ma=fmax(ma,fabs(got[q]-c.gold[q]));ie=fmax(ie,fabs(got[q]-c.ideal[q]));referr=fmax(referr,fabs(got[q]-c.ref[q]));ok&=std::isfinite(got[q])&&fabs(got[q]-c.gold[q])<=1e-4+1e-6*fabs(c.gold[q])&&fabs(got[q]-c.ref[q])<=1e-4+1e-6*fabs(c.ref[q])&&fabs(got[q]-c.ideal[q])<=1e-3;}for(int walker=0;walker<4;walker++){for(int n=0;n<2003;n++){int hb=walker*18036+n*9;sym=fmax(sym,fmax(fabs(h[hb+1]-h[hb+3]),fmax(fabs(h[hb+2]-h[hb+6]),fabs(h[hb+5]-h[hb+7]))));if(!c.kind)ce=fmax(ce,fabs(v[walker*2003+n]-float(n%17-8)/16.f));}for(int q=6009;q<6012;q++)ok&=g[walker*6012+q]==-123.25f;for(int q=18027;q<18036;q++)ok&=h[walker*18036+q]==-123.25f;}output.insert(output.end(),got.begin(),got.end());}ok&=sym==0&&ce<=5e-6;allok&=ok;char file[80];sprintf(file,"bspline_trial%d.bin",trial);FILE*o=fopen(file,"wb");fwrite(output.data(),4,output.size(),o);fclose(o);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"computed_output_values\":208312,\"defined_padding_values\":96,\"input_prefix_values\":504168,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"ideal_cubic_basis_max_error\":%.12g,\"native_CPU_max_error\":%.12g,\"hessian_symmetry_error\":%.12g,\"constant_value_error\":%.12g,\"timing_region\":\"sum_two_coefficient_fields_four_complete_2003channel_VGH_walkers\",\"jit_excluded\":true,\"internal_repeats\":%d,\"case_times_seconds\":[",trial,seconds,ok?"true":"false",output.size(),ma,ie,referr,sym,ce,repeat);for(int q=0;q<8;q++)printf("%s%.12g",q?",":"",times[q]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",file,output.size());}for(auto&c:cases){CK(cudaFree(c.coefs));CK(cudaFree(c.vals));CK(cudaFree(c.grads));CK(cudaFree(c.hess));}CK(cudaFree(dw));puts(allok?"PASS":"FAIL");return allok?0:1;}
